-- 0004_data_model.sql — Phase-1 data model (DATA-MODEL-PHASE1-SPEC §4,
-- DM-1…DM-31). STRICTLY ADDITIVE (MIG-1): 0000/0001/0002/0003 are untouched and
-- `companies` is not altered at all (DM-1) — the VSME reporting profile moves
-- semantically to `legal_entity`, the tenant columns stay where they are.
--
-- Hand-authored, like every migration in this project: `drizzle-kit generate` is
-- NEVER run here (§0.4, drizzle/README.md) and `meta/_journal.json` carries a
-- hand-written `idx: 4` entry. `src/server/db/schema.ts` mirrors this file for
-- the ORM; THIS FILE IS THE SOURCE OF TRUTH, and the eight partial/expression
-- indexes marked "PAIR (R-1)" below exist in both places with nothing checking
-- them against each other — edit them together.
--
-- Order: reference data → org axis → period → revision → input → evidence/DQ/
-- validation → derived. It is FK order: every table's targets already exist.
--
-- CHECK policy (§0.8). Domain lists (fuels, units, facility types, …) are plain
-- `text` with no CHECK — they live in `src/shared/enums/` so that adding a value
-- is a data-only change. CHECKs appear only on: lifecycle columns (`state`,
-- `report_revision.status`, `period_scope.status`, `factor_set.status`),
-- structural discriminators (`activity_category`, `energy_type`,
-- `calculation.reporting_basis`, `reporting_period.reporting_basis`,
-- `validation_result.scope`), definitional ranges/formats (DQ 1–5 and 0–100,
-- `year_month` = YYYY-MM, `start_date < end_date`) and the render invariants
-- (`format`, `language`, `coverage_claim` + the D14 rule DM-31).

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 1. REFERENCE DATA — read-only catalogues, shared by every tenant          ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

-- DM-20: the disclosure catalogue. `standard`/`pillar` exist from day one so
-- ESRS/GRI (К-26) need no DDL later; Phase 1 seeds only the 141 VSME rows.
-- `*_en` (О-20) hold the standard's own English wording next to the workbook's
-- Russian DM-20 names: the product's locales are `en`/`sl` and the VSME renderer
-- (`report_render.language`, О-14) must never print a Russian label.
CREATE TABLE IF NOT EXISTS metric_catalog (
  metric_key              text PRIMARY KEY,           -- 'VSME-001' … 'VSME-141'
  standard                text NOT NULL DEFAULT 'vsme',
  pillar                  text NOT NULL,              -- general|environmental|social|governance
  module                  text NOT NULL,              -- basic|comprehensive
  disclosure_code         text NOT NULL,              -- B1…B11, C1…C9
  disclosure_title        text,
  disclosure_title_en     text,                       -- О-20; renderer-facing section heading
  paragraph               text,
  requirement_type        text NOT NULL,              -- mandatory|conditional|voluntary (О-19)
  title                   text NOT NULL,
  title_en                text,                       -- О-20; renderer-facing metric label
  description             text,
  unit                    text,
  applicability_condition text,
  value_type              text NOT NULL,              -- one of the 12 DataType (S1)
  breakdown_dimensions    jsonb,                      -- S1; whole value lives in value_json
  guidance                text,
  sort_order              integer NOT NULL,
  is_active               boolean NOT NULL DEFAULT true
);

-- DM-21: a released factor set. A period PINS one; a release is a NEW set.
CREATE TABLE IF NOT EXISTS factor_set (
  id           uuid PRIMARY KEY,
  code         text NOT NULL,                         -- 'legacy-v1', 'defra-2025-v1'
  name         text NOT NULL,
  description  text,
  status       text NOT NULL DEFAULT 'draft',
  published_at timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT factor_set_code_key UNIQUE (code),
  CONSTRAINT factor_set_status_check CHECK (status IN ('draft','active','archived'))
);

-- DM-22: one factor inside a set. NO `CHECK (factor_value > 0)` — a legitimate
-- zero exists (VAL-033); "never a silent zero" is a calculation rule (§0.7).
CREATE TABLE IF NOT EXISTS emission_factor (
  id                 uuid PRIMARY KEY,
  factor_set_id      uuid NOT NULL REFERENCES factor_set(id) ON DELETE CASCADE,
  factor_code        text NOT NULL,
  factor_name        text NOT NULL,
  source_name        text NOT NULL,                   -- DEFRA/IEA/ADEME/EPA/supplier/custom
  source_version     text NOT NULL,
  publication_date   date,
  applicable_year    integer,
  geography          text NOT NULL,                   -- country / region / 'GLOBAL'
  activity_type      text NOT NULL,
  input_unit         text NOT NULL,
  factor_value       numeric NOT NULL,                -- kgCO2e per input unit
  output_unit        text NOT NULL DEFAULT 'kgCO2e',
  co2_value          numeric,
  ch4_value          numeric,
  n2o_value          numeric,
  gwp_basis          text,                            -- AR5|AR6
  wtt_included       boolean NOT NULL DEFAULT false,
  biogenic_treatment text,                            -- fossil|biogenic
  rf_included        boolean,
  valid_from         date,
  valid_to           date,
  source_url         text,
  source_locator     text,
  licence            text,
  status             text NOT NULL DEFAULT 'active'
);

-- [INDEX 6/8] EXPRESSION unique — VAL-031: one factor per (set, source+version,
-- activity, geography, unit, year).
-- О-18: `applicable_year` added beyond §4 DM-22. Uniqueness must mirror the
-- CALC-2 resolve key, which IS year-aware; without the year one source that
-- prices several years (AIB grid: the same country in 2023/2024/2025) collides
-- with itself, and the legacy set alone would lose 224 of 440 rows.
-- COALESCE, not a plain UNIQUE: `applicable_year` is nullable and the 14
-- refrigerant factors leave it NULL (a GWP is year-independent). Postgres treats
-- NULLs as DISTINCT in a UNIQUE, so a table constraint could not stop a second
-- copy of a refrigerant row — the seed's purity was the only thing that did, and
-- T2.8's admin factor screen would take that away, leaving CALC-2 to discover the
-- duplicate as a runtime FACTORS_AMBIGUOUS. `-1` is the sentinel: `applicable_year`
-- is an integer and no real year can be negative. `geography` needs no such
-- treatment — it is NOT NULL (missing country normalises to 'GLOBAL').
-- PAIR (R-1): schema.ts `emissionFactor`.
CREATE UNIQUE INDEX IF NOT EXISTS emission_factor_resolution_key
  ON emission_factor (
    factor_set_id,
    source_name,
    source_version,
    activity_type,
    geography,
    input_unit,
    COALESCE(applicable_year, -1)
  );

-- DM-23: unit conversions (D7). NULL activity_context = universal physical
-- conversion (kWh→MWh); non-null = contextual calorific (natural_gas: m3→kWh).
CREATE TABLE IF NOT EXISTS unit_conversion (
  id               uuid PRIMARY KEY,
  from_unit        text NOT NULL,
  to_unit          text NOT NULL,
  multiplier       numeric NOT NULL,                  -- to = from × multiplier
  activity_context text,
  source           text,
  notes            text
);

-- [INDEX 7/8] EXPRESSION unique — COALESCE placeholder for the nullable
-- context, precedent `emission_factors` in 0000. drizzle-kit truncates the
-- string literal, so it is hand-authored. PAIR (R-1): schema.ts `unitConversion`.
CREATE UNIQUE INDEX IF NOT EXISTS unit_conversion_from_to_context_key
  ON unit_conversion (from_unit, to_unit, COALESCE(activity_context, '--'));

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 2. ORGANISATIONAL AXIS — company → legal_entity → facility (+ asset)      ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

-- DM-2: the VSME B1 profile lives here, not on `companies` (К-1) — a subsidiary
-- needs its own. Effective-dated (F4). Hierarchy cycles are rejected app-side
-- by a recursive CTE (DM-3); deletion of an entity with data is refused app-side
-- (DM-4) — leaving a group is `effective_to`, not a DELETE.
CREATE TABLE IF NOT EXISTS legal_entity (
  id                     uuid PRIMARY KEY,
  company_id             uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  name                   text NOT NULL,               -- DD organisation_name (К-1)
  registration_number    text,                        -- required app-side (VAL-001)
  vat_number             text,
  registered_address     text,                        -- required when included (VAL-103)
  country                char(2),                     -- ISO-3166
  nace_code              text,
  reporting_currency     char(3) REFERENCES currencies(code),
  employee_count         integer,
  average_fte            numeric,
  turnover               numeric,                     -- in reporting_currency (VSME B3)
  group_structure_type   text,                        -- standalone|parent|subsidiary
  parent_legal_entity_id uuid REFERENCES legal_entity(id),  -- К-2, self-FK
  consolidation_method   text,                        -- operational/financial control, equity share
  ownership_percentage   numeric,                     -- 0–100 (F4), app-validated
  effective_from         date,
  effective_to           date,                        -- ≥ effective_from (VAL-004)
  exclusion_reason       text,                        -- registry-level; per-period → period_scope
  created_at             timestamptz DEFAULT now(),
  updated_at             timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS legal_entity_company_idx ON legal_entity (company_id);
CREATE INDEX IF NOT EXISTS legal_entity_parent_idx  ON legal_entity (parent_legal_entity_id);

-- DM-5: a site. `included_in_boundary` is the REGISTRY flag; the per-period
-- decision is a `period_scope` row on the owning legal entity (D10/D15).
CREATE TABLE IF NOT EXISTS facility (
  id                      uuid PRIMARY KEY,
  company_id              uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  legal_entity_id         uuid NOT NULL REFERENCES legal_entity(id),   -- VAL-005
  facility_name           text NOT NULL,
  facility_type           text,                       -- office/plant/warehouse/store/farm/other
  address                 text,
  country                 char(2),                    -- picks the grid factor (VAL-021)
  postal_code             text,
  latitude                numeric,                    -- −90…90, app-validated (VAL-006)
  longitude               numeric,                    -- −180…180 (VAL-006)
  tenure                  text,                       -- owned|leased|managed|shared
  control_status          text,                       -- controlled|not_controlled
  floor_area              numeric,                    -- m²
  opening_date            date,
  closing_date            date,
  included_in_boundary    boolean NOT NULL DEFAULT true,
  boundary_classification text,                       -- BoundaryTreatment
  created_at              timestamptz DEFAULT now(),
  updated_at              timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS facility_company_idx      ON facility (company_id);
CREATE INDEX IF NOT EXISTS facility_legal_entity_idx ON facility (legal_entity_id);

-- DM-6: a flat registry (vehicle, building, equipment, generator, METER, other).
-- Not a level of the org tree and not counted by plan limits (F5). `meter_id` of
-- the DD is `meter_asset_id` on purchased energy (К-7).
CREATE TABLE IF NOT EXISTS asset (
  id              uuid PRIMARY KEY,
  company_id      uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  legal_entity_id uuid NOT NULL REFERENCES legal_entity(id),
  facility_id     uuid REFERENCES facility(id),
  name            text NOT NULL,
  asset_type      text NOT NULL,                      -- vehicle|building|equipment|generator|meter|other
  identifier      text,                               -- plate, serial, meter number
  notes           text,
  created_at      timestamptz DEFAULT now(),
  updated_at      timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS asset_company_idx  ON asset (company_id);
CREATE INDEX IF NOT EXISTS asset_facility_idx ON asset (facility_id);

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 3. REPORTING PERIOD AND ITS BOUNDARY                                      ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

-- DM-7: arbitrary dates + a PINNED factor set — that pin is what makes AC-8
-- (reproducing a locked revision) possible. There is NO `period_status` column
-- (К-4): the status of a period is the status of its current revision.
-- Overlapping periods are a warning (VAL-009), not a constraint. The
-- calculation-relevant fields are frozen once the current revision leaves
-- draft/rejected (DM-7a, VAL-106) — an application rule, not DDL.
CREATE TABLE IF NOT EXISTS reporting_period (
  id                    uuid PRIMARY KEY,
  company_id            uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  period_name           text NOT NULL,
  start_date            date NOT NULL,
  end_date              date NOT NULL,
  reporting_year        integer NOT NULL,
  base_year             integer,
  reporting_basis       text NOT NULL DEFAULT 'individual',   -- К-13
  methodology_version   text NOT NULL,                        -- К-19: text, not FK
  factor_set_id         uuid NOT NULL REFERENCES factor_set(id),  -- К-24
  comparative_period_id uuid REFERENCES reporting_period(id),
  created_by            uuid REFERENCES profiles(id),         -- DM-13
  created_at            timestamptz DEFAULT now(),
  updated_at            timestamptz DEFAULT now(),
  CONSTRAINT reporting_period_dates_check CHECK (start_date < end_date),  -- VAL-008
  CONSTRAINT reporting_period_reporting_basis_check
    CHECK (reporting_basis IN ('individual','consolidated'))
);
CREATE INDEX IF NOT EXISTS reporting_period_company_year_idx
  ON reporting_period (company_id, reporting_year);

-- DM-8: the boundary — one row per (period, legal entity) plus the reason an
-- entity is out (mandatory when 'excluded', VAL-101). Changes are audited and
-- only allowed while the current revision is draft/rejected (DM-9).
CREATE TABLE IF NOT EXISTS period_scope (
  id               uuid PRIMARY KEY,
  company_id       uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  period_id        uuid NOT NULL REFERENCES reporting_period(id) ON DELETE CASCADE,
  legal_entity_id  uuid NOT NULL REFERENCES legal_entity(id),
  status           text NOT NULL,
  exclusion_reason text,
  updated_by       uuid REFERENCES profiles(id),      -- DM-13
  updated_at       timestamptz DEFAULT now(),
  CONSTRAINT period_scope_status_check
    CHECK (status IN ('included','excluded','not_applicable','not_assessed')),
  CONSTRAINT period_scope_period_entity_key UNIQUE (period_id, legal_entity_id)
);

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 4. THE ONE STATE MACHINE (D22)                                            ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

-- DM-10: the only stateful workflow entity in Phase 1 (§0.5). Promotion is a
-- status transition, never a copy; a restatement is a NEW revision seeded from
-- the locked one. `frozen_scope` is written at Lock — the boundary snapshot plus
-- the calculation-relevant period fields, i.e. the input of a reproducible
-- recalculation (CALC-7, D15).
CREATE TABLE IF NOT EXISTS report_revision (
  id                      uuid PRIMARY KEY,
  company_id              uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  period_id               uuid NOT NULL REFERENCES reporting_period(id) ON DELETE CASCADE,
  revision_no             integer NOT NULL,
  status                  text NOT NULL DEFAULT 'draft',
  is_current              boolean NOT NULL DEFAULT true,
  assigned_to             uuid REFERENCES profiles(id),   -- current reviewer (DM-13)
  review_comment          text,
  -- О-16: spec §4.7 stamps `reviewed_at`/`locked_at` with no actor beside them.
  -- `assigned_to` cannot serve as one — it is MUTABLE, so a reassignment erases
  -- who actually rejected or locked the revision. `audit_log` keeps the
  -- transition trail (LC-10); these two keep the same fact on the row itself.
  reviewed_by             uuid REFERENCES profiles(id),   -- DM-13, О-16
  reviewed_at             timestamptz,
  approved_by             uuid REFERENCES profiles(id),
  approved_at             timestamptz,
  change_reason           text,                           -- restatement / reject reason
  seeded_from_revision_id uuid REFERENCES report_revision(id),
  submitted_by            uuid REFERENCES profiles(id),
  submitted_at            timestamptz,
  locked_by               uuid REFERENCES profiles(id),   -- DM-13, О-16
  locked_at               timestamptz,
  frozen_scope            jsonb,
  created_by              uuid NOT NULL REFERENCES profiles(id),
  created_at              timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT report_revision_status_check
    CHECK (status IN ('draft','submitted','in_review','approved','rejected','locked')),
  CONSTRAINT report_revision_period_no_key UNIQUE (period_id, revision_no)
);

-- [INDEX 5/8] PARTIAL unique — exactly one current revision per period.
-- drizzle-kit serializes the WHERE broken → hand-authored.
-- PAIR (R-1): schema.ts `reportRevision`.
CREATE UNIQUE INDEX IF NOT EXISTS report_revision_period_current_key
  ON report_revision (period_id) WHERE is_current;

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 5. INPUT TABLES — D23 lifecycle mixin + a typed body, append-only (§0.4)  ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝
-- The 20 columns between the "lifecycle mixin" markers below are written out per
-- table BECAUSE THIS IS DDL — the single source is `lifecycleColumns()` in
-- `src/server/db/lifecycle.ts`, which every input `pgTable` spreads, and
-- `schema-0004.integration.test.ts` proves all four tables agree column by
-- column (type + nullability). Editing the mixin means editing this file too.
-- `previous_version_id`/`superseded_by_id` are self-FKs; `superseded_by_id` is
-- the ONLY mutable field of an input row, and "current" means it IS NULL.

-- DM-15 (Scope 1): one table for all five categories; `activity_category` is the
-- discriminator that restores the DD's prefixed field names (К-6). The six
-- refrigerant mass-balance columns (К-5) are filled only for fugitive emissions.
CREATE TABLE IF NOT EXISTS emission_activity (
  -- ── lifecycle mixin (DM-11) ──
  id                  uuid PRIMARY KEY,
  company_id          uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  revision_id         uuid NOT NULL REFERENCES report_revision(id),
  legal_entity_id     uuid NOT NULL REFERENCES legal_entity(id),
  facility_id         uuid REFERENCES facility(id),
  asset_id            uuid REFERENCES asset(id),
  metric_key          text REFERENCES metric_catalog(metric_key),
  year_month          text,
  unit                text,
  state               text NOT NULL DEFAULT 'draft',
  approved_by         uuid REFERENCES profiles(id),
  approved_at         timestamptz,
  notes               text,
  previous_version_id uuid REFERENCES emission_activity(id),
  superseded_by_id    uuid REFERENCES emission_activity(id),
  change_reason       text,
  is_deleted          boolean NOT NULL DEFAULT false,
  actor_id            uuid NOT NULL REFERENCES profiles(id),
  actor_role          text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  -- ── body (DM-15) ──
  activity_category     text NOT NULL,
  source_name           text NOT NULL,
  activity_type         text NOT NULL,                -- Fuel/Vehicle/Refrigerant/ProcessType
  activity_value        numeric NOT NULL,             -- ≥ 0 (VAL-011)
  method                text NOT NULL,                -- CalculationMethod (9 values)
  biogenic_flag         boolean,
  refrigerant_added     numeric,                      -- kg, К-5
  refrigerant_recovered numeric,                      -- kg
  equipment_capacity    numeric,                      -- kg
  opening_stock         numeric,                      -- kg
  closing_stock         numeric,                      -- kg
  leakage_rate          numeric,                      -- %
  CONSTRAINT emission_activity_state_check CHECK (state IN ('draft','approved')),
  CONSTRAINT emission_activity_year_month_check
    CHECK (year_month IS NULL OR year_month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  CONSTRAINT emission_activity_category_check CHECK (activity_category IN
    ('stationary_combustion','mobile_combustion','fugitive_emissions',
     'process_emissions','onsite_generation'))
);

-- [INDEX 1/8] PARTIAL — "the current rows of a revision" (§0.4, DM-12).
-- PAIR (R-1): schema.ts `emissionActivity`.
CREATE INDEX IF NOT EXISTS emission_activity_current_idx
  ON emission_activity (revision_id) WHERE superseded_by_id IS NULL;
CREATE INDEX IF NOT EXISTS emission_activity_company_month_idx
  ON emission_activity (company_id, year_month);
CREATE INDEX IF NOT EXISTS emission_activity_legal_entity_idx
  ON emission_activity (legal_entity_id);

-- DM-16 (Scope 2): `energy_type` is the discriminator (К-6). The two
-- `*_factor_id` columns are CALCULATED — the run writes the factor it resolved.
CREATE TABLE IF NOT EXISTS purchased_energy_activity (
  -- ── lifecycle mixin (DM-11) ──
  id                  uuid PRIMARY KEY,
  company_id          uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  revision_id         uuid NOT NULL REFERENCES report_revision(id),
  legal_entity_id     uuid NOT NULL REFERENCES legal_entity(id),
  facility_id         uuid REFERENCES facility(id),
  asset_id            uuid REFERENCES asset(id),
  metric_key          text REFERENCES metric_catalog(metric_key),
  year_month          text,
  unit                text,
  state               text NOT NULL DEFAULT 'draft',
  approved_by         uuid REFERENCES profiles(id),
  approved_at         timestamptz,
  notes               text,
  previous_version_id uuid REFERENCES purchased_energy_activity(id),
  superseded_by_id    uuid REFERENCES purchased_energy_activity(id),
  change_reason       text,
  is_deleted          boolean NOT NULL DEFAULT false,
  actor_id            uuid NOT NULL REFERENCES profiles(id),
  actor_role          text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  -- ── body (DM-16) ──
  energy_type        text NOT NULL,
  supplier           text,
  meter_asset_id     uuid REFERENCES asset(id),       -- К-7
  consumption        numeric NOT NULL,                -- ≥ 0 (VAL-020)
  renewable_share    numeric,                         -- 0–100, app-validated
  location_factor_id uuid REFERENCES emission_factor(id),
  market_factor_id   uuid REFERENCES emission_factor(id),
  CONSTRAINT purchased_energy_activity_state_check CHECK (state IN ('draft','approved')),
  CONSTRAINT purchased_energy_activity_year_month_check
    CHECK (year_month IS NULL OR year_month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  CONSTRAINT purchased_energy_activity_energy_type_check
    CHECK (energy_type IN ('electricity','district_heating','steam','cooling'))
);

-- [INDEX 2/8] PARTIAL (DM-12). PAIR (R-1): schema.ts `purchasedEnergyActivity`.
CREATE INDEX IF NOT EXISTS purchased_energy_activity_current_idx
  ON purchased_energy_activity (revision_id) WHERE superseded_by_id IS NULL;
CREATE INDEX IF NOT EXISTS purchased_energy_activity_company_month_idx
  ON purchased_energy_activity (company_id, year_month);
CREATE INDEX IF NOT EXISTS purchased_energy_activity_legal_entity_idx
  ON purchased_energy_activity (legal_entity_id);

-- DM-17 (D19): market-based Scope 2 instruments. `year_month` is normally NULL
-- — an instrument covers the whole period.
CREATE TABLE IF NOT EXISTS contractual_instrument (
  -- ── lifecycle mixin (DM-11) ──
  id                  uuid PRIMARY KEY,
  company_id          uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  revision_id         uuid NOT NULL REFERENCES report_revision(id),
  legal_entity_id     uuid NOT NULL REFERENCES legal_entity(id),
  facility_id         uuid REFERENCES facility(id),
  asset_id            uuid REFERENCES asset(id),
  metric_key          text REFERENCES metric_catalog(metric_key),
  year_month          text,
  unit                text,
  state               text NOT NULL DEFAULT 'draft',
  approved_by         uuid REFERENCES profiles(id),
  approved_at         timestamptz,
  notes               text,
  previous_version_id uuid REFERENCES contractual_instrument(id),
  superseded_by_id    uuid REFERENCES contractual_instrument(id),
  change_reason       text,
  is_deleted          boolean NOT NULL DEFAULT false,
  actor_id            uuid NOT NULL REFERENCES profiles(id),
  actor_role          text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  -- ── body (DM-17) ──
  instrument_type         text NOT NULL,             -- GoO/REGO/REC/PPA/green_tariff/supplier_product
  certificate_id          text,
  covered_volume          numeric,                   -- MWh
  production_country      char(2),
  technology              text,                      -- GenerationTechnology
  generation_period_start date,
  generation_period_end   date,
  cancellation_date       date,
  quality_criteria_status text,                      -- pass|fail|review
  residual_mix_volume     numeric,                   -- MWh, VAL-024 balance
  CONSTRAINT contractual_instrument_state_check CHECK (state IN ('draft','approved')),
  CONSTRAINT contractual_instrument_year_month_check
    CHECK (year_month IS NULL OR year_month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$')
);

-- [INDEX 3/8] PARTIAL (DM-12). PAIR (R-1): schema.ts `contractualInstrument`.
CREATE INDEX IF NOT EXISTS contractual_instrument_current_idx
  ON contractual_instrument (revision_id) WHERE superseded_by_id IS NULL;
CREATE INDEX IF NOT EXISTS contractual_instrument_company_month_idx
  ON contractual_instrument (company_id, year_month);
CREATE INDEX IF NOT EXISTS contractual_instrument_legal_entity_idx
  ON contractual_instrument (legal_entity_id);

-- DM-18: scalar/narrative disclosures typed by `value_type` (the 12 DataType of
-- S1). Exactly one value column is non-empty (DM-19, app-checked); a metric with
-- `breakdown_dimensions` lives ENTIRELY in `value_json` — total included — so
-- the total and the breakdown cannot drift apart. `metric_key` is the one mixin
-- column this table narrows to NOT NULL.
CREATE TABLE IF NOT EXISTS disclosure_record (
  -- ── lifecycle mixin (DM-11) ──
  id                  uuid PRIMARY KEY,
  company_id          uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  revision_id         uuid NOT NULL REFERENCES report_revision(id),
  legal_entity_id     uuid NOT NULL REFERENCES legal_entity(id),
  facility_id         uuid REFERENCES facility(id),
  asset_id            uuid REFERENCES asset(id),
  metric_key          text NOT NULL REFERENCES metric_catalog(metric_key),  -- DM-18
  year_month          text,
  unit                text,
  state               text NOT NULL DEFAULT 'draft',
  approved_by         uuid REFERENCES profiles(id),
  approved_at         timestamptz,
  notes               text,
  previous_version_id uuid REFERENCES disclosure_record(id),
  superseded_by_id    uuid REFERENCES disclosure_record(id),
  change_reason       text,
  is_deleted          boolean NOT NULL DEFAULT false,
  actor_id            uuid NOT NULL REFERENCES profiles(id),
  actor_role          text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  -- ── body (DM-18) ──
  value_type    text NOT NULL,                       -- one of the 12 DataType
  value_numeric numeric,                             -- Integer/Decimal/Percentage
  value_text    text,                                -- String/Text
  value_boolean boolean,                             -- Boolean
  value_date    date,                                -- Date
  value_json    jsonb,                               -- Enum/Multi-*/Reference/breakdowns
  CONSTRAINT disclosure_record_state_check CHECK (state IN ('draft','approved')),
  CONSTRAINT disclosure_record_year_month_check
    CHECK (year_month IS NULL OR year_month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$')
);

-- [INDEX 4/8] PARTIAL (DM-12). PAIR (R-1): schema.ts `disclosureRecord`.
CREATE INDEX IF NOT EXISTS disclosure_record_current_idx
  ON disclosure_record (revision_id) WHERE superseded_by_id IS NULL;
CREATE INDEX IF NOT EXISTS disclosure_record_company_month_idx
  ON disclosure_record (company_id, year_month);
CREATE INDEX IF NOT EXISTS disclosure_record_legal_entity_idx
  ON disclosure_record (legal_entity_id);

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 6. EVIDENCE, DATA QUALITY, VALIDATION                                     ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

-- DM-24: file metadata; the bytes live in the blob store behind `storage_key`
-- (EV-0). `file_hash` is indexed but NOT unique — a duplicate upload is a
-- warning (VAL-013), not an error.
CREATE TABLE IF NOT EXISTS document (
  id              uuid PRIMARY KEY,
  company_id      uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  file_name       text NOT NULL,
  file_type       text NOT NULL,                     -- pdf|xlsx|csv|image|other
  mime            text,
  storage_key     text NOT NULL,
  size_bytes      bigint,
  file_hash       char(64) NOT NULL,                 -- SHA-256 hex
  issuer          text,
  document_date   date,
  coverage_start  date,
  coverage_end    date,
  confidentiality text NOT NULL DEFAULT 'internal',  -- public|internal|confidential
  retention_date  date,
  uploaded_by     uuid NOT NULL REFERENCES profiles(id),   -- DM-13
  uploaded_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS document_company_hash_idx ON document (company_id, file_hash);

-- DM-25: the polymorphic M:N link (К-8) — one invoice can stand behind many
-- rows. A link points at a SPECIFIC immutable row version; the service layer
-- re-points links when a row is superseded. Discarding a revision never deletes
-- a document (DM-26); deleting the document does delete its links.
CREATE TABLE IF NOT EXISTS evidence_link (
  id                 uuid PRIMARY KEY,
  company_id         uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  document_id        uuid NOT NULL REFERENCES document(id) ON DELETE CASCADE,
  linked_object_type text NOT NULL,                  -- ObjectType = table name
  linked_object_id   uuid NOT NULL,
  created_by         uuid REFERENCES profiles(id),   -- DM-13
  created_at         timestamptz DEFAULT now(),
  CONSTRAINT evidence_link_target_key
    UNIQUE (document_id, linked_object_type, linked_object_id)
);
-- The UNIQUE above leads with `document_id` and therefore serves "where is this
-- document used". The MAIN read path is the other direction — "which documents
-- back THIS row", one lookup per row rendered in the S4 evidence panel — and it
-- would be a seq scan without this index.
CREATE INDEX IF NOT EXISTS evidence_link_object_idx
  ON evidence_link (linked_object_type, linked_object_id);

-- DM-27: one assessment per row VERSION (К-16, К-23). On a new version the
-- service layer copies it forward; the old version keeps its own — the history.
CREATE TABLE IF NOT EXISTS dq_assessment (
  id                   uuid PRIMARY KEY,
  company_id           uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  object_type          text NOT NULL,                -- as in evidence_link
  object_id            uuid NOT NULL,
  reliability_score    integer,
  temporal_score       integer,
  geographical_score   integer,
  technology_score     integer,
  completeness_score   numeric,
  coverage_score       numeric,
  quality_tier         text,                         -- high_primary|medium_calculated|low_proxy|estimate
  estimate_uncertainty numeric,
  quality_comment      text,
  is_overridden        boolean NOT NULL DEFAULT false,
  override_reason      text,                         -- mandatory when overridden (VAL-039)
  assessed_by          uuid REFERENCES profiles(id), -- DM-13
  assessed_at          timestamptz DEFAULT now(),
  CONSTRAINT dq_assessment_reliability_score_check
    CHECK (reliability_score IS NULL OR reliability_score BETWEEN 1 AND 5),
  CONSTRAINT dq_assessment_temporal_score_check
    CHECK (temporal_score IS NULL OR temporal_score BETWEEN 1 AND 5),
  CONSTRAINT dq_assessment_geographical_score_check
    CHECK (geographical_score IS NULL OR geographical_score BETWEEN 1 AND 5),
  CONSTRAINT dq_assessment_technology_score_check
    CHECK (technology_score IS NULL OR technology_score BETWEEN 1 AND 5),
  CONSTRAINT dq_assessment_completeness_score_check
    CHECK (completeness_score IS NULL OR completeness_score BETWEEN 0 AND 100),
  CONSTRAINT dq_assessment_coverage_score_check
    CHECK (coverage_score IS NULL OR coverage_score BETWEEN 0 AND 100),
  CONSTRAINT dq_assessment_estimate_uncertainty_check
    CHECK (estimate_uncertainty IS NULL OR estimate_uncertainty BETWEEN 0 AND 100),
  CONSTRAINT dq_assessment_object_key UNIQUE (object_type, object_id)
);

-- DM-28: the latest result of one rule against one target. The rule REGISTRY is
-- not a table — `VALIDATION_RULES` is a code constant (F6). `message` holds the
-- canonical RU text (§6.1); the UI renders a translation by `rule_code` (О-12).
CREATE TABLE IF NOT EXISTS validation_result (
  id           uuid PRIMARY KEY,
  company_id   uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  rule_code    text NOT NULL,                        -- VAL-*
  scope        text NOT NULL,
  object_type  text,
  object_id    uuid,
  revision_id  uuid REFERENCES report_revision(id) ON DELETE CASCADE,
  passed       boolean NOT NULL,
  severity     text NOT NULL,                        -- error|warning
  blocking     boolean NOT NULL,
  message      text NOT NULL,
  evaluated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT validation_result_scope_check
    CHECK (scope IN ('record','revision','period','reference_org'))
);

-- [INDEX 8/8] EXPRESSION unique — upsert "latest result per (rule, target)".
-- The nil UUID is the COALESCE placeholder for the nullable target columns, the
-- same trick as '--' on `emission_factors`. PAIR (R-1): schema.ts
-- `validationResult`.
--
-- `company_id` LEADS the key (О-17, a deviation from spec §4.18, which starts at
-- `rule_code`). All three target columns are nullable, so a rule that writes a
-- fully-NULL target — a plausible shape for a reference-org or global check —
-- would collapse to ONE row for the whole installation: company A's result would
-- occupy the slot and company B's upsert would silently overwrite or conflict
-- with it. A cross-tenant collision, latent and horrible to diagnose. The tenant
-- key in front makes the uniqueness per company, which is what "latest result
-- per (rule, target)" always meant.
CREATE UNIQUE INDEX IF NOT EXISTS validation_result_target_key
  ON validation_result (
    company_id,
    rule_code,
    COALESCE(object_type, '--'),
    COALESCE(object_id,  '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(revision_id,'00000000-0000-0000-0000-000000000000'::uuid)
  );
CREATE INDEX IF NOT EXISTS validation_result_revision_idx
  ON validation_result (revision_id);

-- ╔═══════════════════════════════════════════════════════════════════════════╗
-- ║ 7. DERIVED ARTEFACTS — append-only, never stateful (§0.5)                 ║
-- ╚═══════════════════════════════════════════════════════════════════════════╝

-- DM-29: one immutable result row per calculated activity row. `run_id` groups a
-- run (К-25); `factor_snapshot` freezes the factor as it was, which is what makes
-- a locked revision reproducible (AC-8, CALC-7). The activity is addressed
-- polymorphically (К-10) — `source_record` is Phase 2 (F3).
--
-- `revision_id` is NO ACTION, not CASCADE, and that is the AC-8 guarantee in the
-- schema: deleting a revision that has results is REJECTED, so a locked
-- revision cannot lose the numbers that made it reproducible. Tenant deletion is
-- unaffected — `company_id … ON DELETE CASCADE` reaches this table as well, and
-- a NO ACTION FK is checked at END OF STATEMENT, by which point both the
-- revisions and these rows are already gone. Same on `report_render`;
-- `validation_result.revision_id` keeps CASCADE because its rows are recomputable.
CREATE TABLE IF NOT EXISTS calculation (
  id                  uuid PRIMARY KEY,
  company_id          uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  revision_id         uuid NOT NULL REFERENCES report_revision(id),
  run_id              uuid NOT NULL,
  activity_table      text NOT NULL,                 -- К-10, with activity_row_id
  activity_row_id     uuid NOT NULL,
  method_code         text NOT NULL,                 -- CalculationMethod
  formula_version     text NOT NULL,
  input_value         numeric NOT NULL,
  input_unit          text NOT NULL,                 -- К-25, self-describing input
  conversion_factor   numeric NOT NULL DEFAULT 1,    -- D7
  factor_id           uuid REFERENCES emission_factor(id),
  factor_snapshot     jsonb NOT NULL,
  scope               text NOT NULL,                 -- scope1|scope2
  scope3_category     text,                          -- always NULL in Phase 1
  reporting_basis     text,                          -- К-20; NULL for Scope 1
  co2e_result         numeric NOT NULL,              -- kgCO2e
  biogenic_co2_result numeric,                       -- kgCO2, kept apart (VAL-017)
  rounding_rule       text NOT NULL,
  calculated_at       timestamptz NOT NULL DEFAULT now(),
  calculation_status  text NOT NULL,                 -- ok|failed_missing_factor|failed_unit
  CONSTRAINT calculation_reporting_basis_check
    CHECK (reporting_basis IS NULL OR reporting_basis IN ('location_based','market_based'))
);
CREATE INDEX IF NOT EXISTS calculation_revision_run_idx
  ON calculation (revision_id, run_id);
CREATE INDEX IF NOT EXISTS calculation_activity_row_idx
  ON calculation (activity_table, activity_row_id);

-- DM-30: an immutable render instance (NOT the Phase-4 `report_pack` engine,
-- К-12). `language` is the ONE column beyond spec §4.20 (О-14): renders are
-- immutable and hash-pinned, so adding a locale later would mean a migration AND
-- a regeneration of everything already rendered.
-- DM-31 is the last constraint: a render that dropped entities because of the
-- plan can never claim full coverage (D14, "we do not block — we stamp").
CREATE TABLE IF NOT EXISTS report_render (
  id                uuid PRIMARY KEY,
  company_id        uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  revision_id       uuid NOT NULL REFERENCES report_revision(id), -- NO ACTION, as on `calculation`
  pack_code         text NOT NULL DEFAULT 'VSME_BASIC',
  format            text NOT NULL,                   -- pdf|xlsx (К-22)
  language          text NOT NULL,                   -- О-14
  storage_key       text NOT NULL,
  file_hash         char(64) NOT NULL,
  coverage_claim    text NOT NULL,                   -- full|partial (D14)
  completeness_note text,
  excluded_by_plan  jsonb NOT NULL DEFAULT '[]'::jsonb,   -- [{type,id,name}]
  disclaimer_text   text NOT NULL,
  calc_run_id       uuid NOT NULL,                   -- which calculation run is shown
  rendered_by       uuid NOT NULL REFERENCES profiles(id),  -- DM-13
  rendered_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT report_render_format_check CHECK (format IN ('pdf','xlsx')),
  CONSTRAINT report_render_language_check CHECK (language IN ('en','sl')),
  CONSTRAINT report_render_coverage_claim_check CHECK (coverage_claim IN ('full','partial')),
  CONSTRAINT report_render_coverage_claim_d14_check
    CHECK (jsonb_array_length(excluded_by_plan) = 0 OR coverage_claim = 'partial')
);
-- "The renders of this revision" is the only way this table is ever read.
CREATE INDEX IF NOT EXISTS report_render_revision_idx
  ON report_render (revision_id);

-- === REFERENCE DATA (owners: T1.4 metrics, T1.5 factors/units, T1.8 plans.features) ===
--
-- Everything below this marker is DATA, not DDL, and it is appended by the three
-- tasks named above IN THIS FILE — no new migration number is opened (О-13,
-- MIG-6). The reason is deploy-shaped: `deploy.yml` ships `.next/standalone`,
-- `scripts/migrate.mjs` and `drizzle/` to the server and runs the migrator;
-- `src/server/db/seed.ts` and `tsx` NEVER reach it. So the Phase-1 reference
-- minimum — the 141 VSME metrics, `factor_set legacy-v1` + its factors, the unit
-- conversions, and the `plans.features` update — has to travel WITH the
-- migration or production cannot create a period, every disclosure 422s and
-- every calculation fails on a missing factor. The precedent is already in the
-- tree: `0002_data_integrity.sql` inserts `currencies` inline for the same
-- reason. Each block must be idempotent (`INSERT … ON CONFLICT DO NOTHING`), and
-- `seed.ts` becomes a thin wrapper over the same `seed-data/*` source so the two
-- cannot disagree. Appending to an already-written migration is safe only
-- because 0004 is unapplied anywhere until S1 merges, and the [LOCAL-DB] recipe
-- (§0.3) migrates from scratch every time.

